-- Demo data is synthetic and clearly marked.
select 'SURVIVOR', format('VIC_DEMO_%s',8291+n), format('Synthetic survivor %s',n+1),'Rajasthan',case when n%2=0 then 'Jaipur' else 'Udaipur' end from generate_series(1,9) n on conflict (victim_token) do nothing;
select format('SAATH-DEMO-%s',lpad((n+1)::text,3,'0')),format('VIC_DEMO_%s',8291+n),format('+919876543%s',lpad((210+n)::text,3,'0')),'Synthetic demo case','2026-01-18','Rajasthan',case when n%2=0 then 'Jaipur' else 'Udaipur' end,'Support planning','English',true from generate_series(1,9) n on conflict (docket) do nothing;
